'use strict'
/**
 * The agent companion slicer (src/js/33-solution-productionize.js), the
 * productionize prompt it feeds (src/js/react/chatModes.js) and the
 * get_solution_guide lookup (src/js/react/agentTools.js), run on the six
 * real companions.
 *
 * The companions are generated by the docs extensions, so they are fetched
 * from a published site rather than written as fixtures. They are not
 * committed; without them the companion tests are skipped:
 *   node tests/solution-productionize/fetch-companions.mjs
 *
 * The guide links are also checked against the rendered last step of each
 * solution, from the quiz corpus (tests/solution-quiz/build-corpus.mjs), when
 * that corpus and linkedom are both present.
 */
const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const Module = require('node:module')
const esbuild = require('esbuild')

const ROOT = path.join(__dirname, '..', '..')
const CORPUS = path.join(__dirname, '.corpus')
const QUIZ_PAGES = path.join(ROOT, 'tests', 'solution-quiz', '.corpus', 'pages')
const SLUGS = ['multiplayer-gaming', 'sports-data-fanout', 'cdc-to-lakehouse', 'disaster-recovery', 'kafka-migration',
  'kafka-migration-shadowing']
const ORIGIN = 'https://deploy-preview-1--docs.example.test'
// The whole customInstructions string productionize sends: base blocks, the
// mode prompt and the solution block. The five companions measure 8.6k to
// 9.8k. Eval E0 sets the real cap; this keeps growth visible until then.
const INSTRUCTIONS_BUDGET = 12000
const SOLUTION_BLOCK_BUDGET = 5000

const prod = require('../../src/js/33-solution-productionize.js')

function loadEsm (relPath) {
  const filename = path.join(ROOT, relPath)
  const { code } = esbuild.transformSync(fs.readFileSync(filename, 'utf8'), { format: 'cjs', loader: 'js' })
  const mod = new Module(filename, module)
  mod.filename = filename
  mod.paths = Module._nodeModulePaths(path.dirname(filename))
  mod._compile(code, filename)
  return mod.exports
}

const modes = loadEsm('src/js/react/chatModes.js')
const tools = loadEsm('src/js/react/agentTools.js')
const CUSTOM_INSTRUCTIONS = /const CUSTOM_INSTRUCTIONS = `([\s\S]*?)`/.exec(fs.readFileSync(path.join(ROOT, 'src/js/react/AskAI.jsx'), 'utf8'))[1]

let parseHTML = null
try { ({ parseHTML } = require('linkedom')) } catch { /* reported below */ }

const missing = SLUGS.filter((slug) => !fs.existsSync(path.join(CORPUS, slug + '.md')))
const skip = missing.length
  ? 'no companions at tests/solution-productionize/.corpus: run node tests/solution-productionize/fetch-companions.mjs'
  : false

function companion (slug) {
  return fs.readFileSync(path.join(CORPUS, slug + '.md'), 'utf8')
}

// The ### headings under one ## of the raw file, counted without the slicer.
function rawChildren (md, parent) {
  const out = []
  let inside = false
  let fence = false
  for (const line of md.split('\n')) {
    if (/^\s*(```|~~~)/.test(line)) fence = !fence
    if (fence) continue
    if (/^## /.test(line)) inside = line.slice(3).trim() === parent
    else if (inside && /^### /.test(line)) out.push(line.slice(4).trim())
  }
  return out
}

function guideFor (slug, doc) {
  const companionUrl = `${ORIGIN}/solutions/${slug}/agent-companion.md`
  return prod.guideSections(prod.sliceCompanion(prod.rewriteHost(companion(slug), ORIGIN)), {
    doc,
    lastStepUrl: `${ORIGIN}/solutions/${slug}/verify-end-to-end/`,
    stepUrls: Array.from({ length: 12 }, (_, i) => `${ORIGIN}/solutions/${slug}/step-${i + 1}/`),
    companionUrl,
  })
}

function instructionsFor (guide, slug) {
  const def = modes.MODES.productionize
  const detail = {
    title: guide.title,
    solution: slug,
    version: guide.version,
    verifiedVersion: '26.2.1',
    platforms: 'Docker and Redpanda Cloud',
    companionUrl: `${ORIGIN}/solutions/${slug}/agent-companion.md`,
    guideUrl: `${ORIGIN}/solutions/${slug}/`,
    guide,
  }
  // The string App sends, from the same agentProps it spreads.
  const cfg = modes.resolveMode({ mode: 'productionize', ...detail }, { [def.integrationKey]: 'p' }, [])
  const all = modes.agentProps(cfg, {
    instructions: CUSTOM_INSTRUCTIONS,
    modeTools: tools.modeTools,
    knownTools: tools.modeTools.map((t) => t.name),
  }).customInstructions
  return { all, block: modes.productionizeContext(detail) }
}

for (const slug of SLUGS) {
  test(`${slug}: every fixed section parses`, { skip }, () => {
    const sliced = prod.sliceCompanion(companion(slug))
    const titles = sliced.sections.map((s) => s.title)
    for (const name of ['Rules', 'Adapt', 'System map', 'Design contract', 'Acceptance', 'Production gaps', 'Reference build']) {
      assert.ok(titles.includes(name), `${slug} has no ## ${name}: ${titles.join(', ')}`)
    }
    assert.ok(sliced.title && !sliced.title.startsWith('Agent companion'), 'the title drops its prefix')
    assert.match(sliced.version, /^v\d+\.\d+\.\d+$/, 'the companion names the version it was generated from')
  })

  test(`${slug}: one topic per ### under Production gaps, one step per Design contract entry`, { skip }, () => {
    const md = companion(slug)
    const guide = guideFor(slug)
    assert.deepEqual(guide.topics, rawChildren(md, 'Production gaps'))
    // Some companions keep most of Production gaps in its overview, before
    // the first topic.
    assert.ok(guide.topics.length >= 1, `${slug} has ${guide.topics.length} topics`)
    const entries = rawChildren(md, 'Design contract').filter((t) => /^\d+\. /.test(t))
    assert.equal(guide.steps, entries.length)
    // One rule per step, in the same order.
    const rules = guide.rules.split('\n').filter((l) => /^\d+\. /.test(l))
    assert.equal(rules.length, guide.steps, 'one rule per Design contract entry')
  })

  test(`${slug}: Acceptance is the top-level section, not the reference's own checks`, { skip }, () => {
    const guide = guideFor(slug)
    const acceptance = tools.findGuideSection(guide, 'Acceptance')
    assert.match(acceptance.text, /every rule holds/i)
    assert.doesNotMatch(acceptance.text, /make verify/)
    // Reference build, whole or as its sub-sections, holds the reference's checks.
    const reference = guide.sections.filter((s) => s.section === 'Reference build' || s.parent === 'Reference build')
    assert.match(reference.map((s) => s.text).join('\n'), /### Acceptance checks of the reference/)
  })

  test(`${slug}: no production solution link survives the host rewrite`, { skip }, () => {
    const guide = guideFor(slug)
    const everything = JSON.stringify(guide) + instructionsFor(guide, slug).all
    assert.ok(!everything.includes('docs.redpanda.com/solutions/'), 'a docs.redpanda.com/solutions/ link was left')
    assert.ok(everything.includes(`${ORIGIN}/solutions/${slug}/`), 'the rewritten links point at the page origin')
    // Product docs links are not the solution's, so they stay on production.
    assert.ok(everything.includes('https://docs.redpanda.com/streaming/'))
  })

  test(`${slug}: the assembled instructions stay under budget`, { skip }, () => {
    const { all, block } = instructionsFor(guideFor(slug), slug)
    assert.ok(block.length <= SOLUTION_BLOCK_BUDGET, `solution block is ${block.length} characters`)
    assert.ok(all.length <= INSTRUCTIONS_BUDGET, `customInstructions is ${all.length} characters`)
    // The block carries the rules and the topic names, never the gap text.
    const guide = guideFor(slug)
    assert.ok(block.includes(guide.rules))
    for (const topic of guide.topics) assert.ok(block.includes(topic), topic)
    const gap = tools.findGuideSection(guide, guide.topics[0]).text
    assert.ok(!all.includes(gap.slice(0, 200)), 'gap text stays out of the prompt')
  })

  test(`${slug}: get_solution_guide answers every section it lists`, { skip }, () => {
    const guide = guideFor(slug)
    for (const s of guide.sections) {
      const hit = tools.findGuideSection(guide, s.section.toUpperCase())
      assert.equal(hit.section, s.section)
      assert.ok(hit.text.length > 0 && hit.text.length <= tools.GUIDE_SECTION_MAX_CHARS, `${s.section}: ${hit.text.length}`)
      assert.ok(hit.guide_url.startsWith(ORIGIN + '/solutions/' + slug + '/'), `${s.section}: ${hit.guide_url}`)
    }
    assert.equal(tools.findGuideSection(guide, 'step 2').section, 'step:2')
    assert.equal(tools.findGuideSection(guide, 'step:2').guide_url, `${ORIGIN}/solutions/${slug}/step-2/`)
    const miss = tools.findGuideSection(guide, 'Kubernetes operators on Mars')
    assert.equal(miss.error, 'not_found')
    assert.deepEqual(miss.available, guide.sections.map((s) => s.section))
  })
}

test('a Reference build longer than the cap comes as sub-sections named in the prompt', { skip }, () => {
  const guide = guideFor('sports-data-fanout')
  const raw = prod.sliceCompanion(prod.rewriteHost(companion('sports-data-fanout'), ORIGIN)).sections
    .find((s) => s.title === 'Reference build')
  assert.ok(raw.text.length > tools.GUIDE_SECTION_MAX_CHARS, 'sports-data-fanout has a Reference build over the cap')
  const pieces = guide.sections.filter((s) => s.parent === 'Reference build')
  assert.ok(pieces.length > 1)
  assert.equal(pieces.map((s) => s.text).join('').replace(/\s+/g, ''), raw.text.replace(/\s+/g, ''))
  const { block } = instructionsFor(guide, 'sports-data-fanout')
  for (const p of pieces) assert.ok(block.includes(p.section), p.section)
  const hit = tools.findGuideSection(guide, 'Reference build')
  assert.equal(hit.section, 'Reference build: overview')
  assert.doesNotMatch(hit.text, /https?:/)
})

test('get_solution_guide passes the provider context to the lookup', { skip }, async () => {
  const guide = guideFor('kafka-migration')
  const tool = tools.productionizeTools.find((t) => t.name === 'get_solution_guide')
  const hit = await tool.execute({ section: 'Rollback' }, { solutionGuide: guide })
  assert.equal(hit.section, 'Rollback')
  assert.deepEqual(await tool.execute({ section: 'Rollback' }, {}), {
    error: 'unavailable', message: 'The production guide for this solution is not loaded.',
  })
})

test('a heading inside a code fence is text, not a section', () => {
  const md = '# Agent companion: T\n\nGenerated from the t solution (v1.2.3).\n\n## Production gaps\n\n### Real\n\n```sh\n### not a heading\n## nor this\n```\n\nafter\n\n## Acceptance\n\ndone\n'
  const sliced = prod.sliceCompanion(md)
  assert.deepEqual(sliced.sections.map((s) => s.title), ['Production gaps', 'Acceptance'])
  assert.deepEqual(sliced.sections[0].children.map((c) => c.title), ['Real'])
  assert.match(sliced.sections[0].children[0].text, /### not a heading[\s\S]*after/)
  assert.equal(sliced.version, 'v1.2.3')
})

// The rendered last steps. Two solutions set custom ids on a topic heading
// ("prod-recovery-point-and-time" for "Recovery point and recovery time"), so
// a slug of the topic text alone misses them; the heading text matches.
const pagesSkip = skip || (!parseHTML
  ? 'linkedom is not installed (npm ci)'
  : !fs.existsSync(QUIZ_PAGES)
    ? 'no rendered pages at tests/solution-quiz/.corpus: see tests/solution-quiz/build-corpus.mjs'
    : false)

test('every gap topic links to its own heading on the rendered last step', { skip: pagesSkip }, () => {
  let bySlug = 0
  let total = 0
  for (const slug of SLUGS) {
    const file = path.join(QUIZ_PAGES, slug, 'verify-end-to-end.html')
    const { document } = parseHTML(fs.readFileSync(file, 'utf8'))
    const ids = new Set(Array.from(document.querySelectorAll('h3[id^="prod-"]')).map((h) => h.id))
    const guide = guideFor(slug, document)
    for (const topic of guide.topics) {
      total++
      const url = guide.sections.find((s) => s.section === topic).guide_url
      const id = url.split('#')[1]
      assert.ok(ids.has(id), `${slug} "${topic}" links to #${id}, which is not on the page`)
      if (id === 'prod-' + topic.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')) bySlug++
    }
    assert.ok(document.getElementById('production-considerations'), `${slug} has the fallback anchor`)
    // The two corpora come from different builds (a published companion, a
    // pinned redpanda-solutions commit), so check they describe the same
    // solution: the same version, and a topic for every heading on the page.
    assert.equal(guide.version, document.body.getAttribute('data-solution-version'), `${slug}: companion and pages are different versions`)
    const linked = new Set(guide.topics.map((topic) => guide.sections.find((s) => s.section === topic).guide_url.split('#')[1]))
    for (const id of ids) assert.ok(linked.has(id), `${slug}: #${id} on the page has no topic in the companion`)
  }
  assert.ok(bySlug < total, 'some heading ids differ from the slug of their text, so the text match is what finds them')
})

test('a topic with no heading on the page falls back to Production considerations', () => {
  const doc = { querySelectorAll: () => [{ id: 'prod-security', textContent: 'Security' }] }
  assert.equal(prod.gapUrl(doc, 'Security', 'https://x.test/s/last/#old'), 'https://x.test/s/last/#prod-security')
  assert.equal(prod.gapUrl(doc, 'Rollback', 'https://x.test/s/last/'), 'https://x.test/s/last/#production-considerations')
  assert.equal(prod.gapUrl(null, 'Rollback', 'https://x.test/s/last/'), 'https://x.test/s/last/#production-considerations')
})
